import { createReadStream, existsSync } from 'node:fs';
import { Router, type Request, type Response } from 'express';
import { authMiddleware } from '../auth.js';
import { getMedia } from '../store.js';

export const mediaRouter = Router();

mediaRouter.get('/media/:id', authMiddleware, (req: Request, res: Response) => {
  const id = req.params.id as string;
  const media = getMedia(id);
  if (!media || !existsSync(media.path)) {
    res.status(404).json({ error: 'not_found' });
    return;
  }
  res.setHeader('Content-Type', media.mime);
  if (typeof media.size === 'number') {
    res.setHeader('Content-Length', String(media.size));
  }
  createReadStream(media.path).pipe(res);
});
